export class BodyModelViewerComponent {
    constructor(bodyModelService) {
        this.bodyModelService = bodyModelService;
        this.bodyPartSelected = new EventEmitter();
        this.raycaster = new THREE.Raycaster();
        this.mouse = new THREE.Vector2();
        // 狀態管理
        this.isModelVisible = false;
        this.selectedParts = [];
        this.hoveredPart = null;
        this.loadingProgress = { loaded: 0, total: 0, percentage: 0 };
        this.mousePosition = { x: 0, y: 0 };
        // 點選回饋效果
        this.showClickNotification = false;
        this.clickPosition = { x: 0, y: 0 };
        this.lastSelectedPart = null;
        this.subscriptions = [];
        this.animationId = null;
    }
    async ngOnInit() {
        this.initThreeJS();
        this.setupEventListeners();
        this.subscribeToServices();
        this.startRenderLoop();
    }
    ngOnDestroy() {
        this.cleanup();
    }
    initThreeJS() {
        const canvas = this.canvasRef.nativeElement;
        // 場景設置
        this.scene = new THREE.Scene();
        this.scene.background = new THREE.Color(0xf0f0f0);
        // 相機設置
        this.camera = new THREE.PerspectiveCamera(45, canvas.clientWidth / canvas.clientHeight, 0.1, 1000);
        this.camera.position.set(0, 0, 8);
        // 渲染器設置
        this.renderer = new THREE.WebGLRenderer({
            canvas,
            antialias: true,
            alpha: true
        });
        this.renderer.setSize(canvas.clientWidth, canvas.clientHeight);
        this.renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
        this.renderer.shadowMap.enabled = true;
        this.renderer.shadowMap.type = THREE.PCFSoftShadowMap;
        this.renderer.outputEncoding = THREE.sRGBEncoding;
        // 控制器設置
        this.controls = new OrbitControls(this.camera, canvas);
        this.controls.enableDamping = true;
        this.controls.dampingFactor = 0.05;
        this.controls.maxDistance = 20;
        this.controls.minDistance = 2;
        // 光照設置
        const ambientLight = new THREE.AmbientLight(0xffffff, 0.6);
        const directionalLight = new THREE.DirectionalLight(0xffffff, 0.8);
        directionalLight.position.set(10, 10, 5);
        directionalLight.castShadow = true;
        directionalLight.shadow.mapSize.setScalar(2048);
        this.scene.add(ambientLight);
        this.scene.add(directionalLight);
    }
    setupEventListeners() {
        const canvas = this.canvasRef.nativeElement;
        canvas.addEventListener('click', (event) => this.onCanvasClick(event));
        canvas.addEventListener('mousemove', (event) => this.onMouseMove(event));
        canvas.addEventListener('mouseleave', () => this.onMouseLeave());
        window.addEventListener('resize', () => this.onWindowResize());
    }
    subscribeToServices() {
        // 訂閱選擇狀態
        const selectedSub = this.bodyModelService.selectedParts$.subscribe(parts => this.selectedParts = parts);
        // 訂閱載入進度
        const progressSub = this.bodyModelService.loadingProgress$.subscribe(progress => this.loadingProgress = progress);
        this.subscriptions.push(selectedSub, progressSub);
    }
    async toggleModelDisplay() {
        if (!this.isModelVisible) {
            // 載入模型
            try {
                // 假設您將女性模型轉換後放在這個路徑
                const model = await this.bodyModelService.loadModel('/assets/models/test2-female-body.glb');
                this.scene.add(model);
                this.isModelVisible = true;
            }
            catch (error) {
                console.error('載入模型失敗:', error);
                alert('載入3D模型失敗，請檢查模型檔案是否存在');
            }
        }
        else {
            // 隱藏模型
            this.isModelVisible = false;
            this.clearModelsFromScene();
        }
    }
    clearModelsFromScene() {
        const objectsToRemove = [];
        this.scene.traverse((child) => {
            if (child.userData && child.userData['isBodyModel']) {
                objectsToRemove.push(child);
            }
        });
        objectsToRemove.forEach(obj => this.scene.remove(obj));
    }
    // 實作 ChatGPT 建議的點擊檢測
    onCanvasClick(event) {
        if (!this.isModelVisible)
            return;
        const canvas = this.canvasRef.nativeElement;
        const rect = canvas.getBoundingClientRect();
        // 轉換滑鼠座標
        this.mouse.x = ((event.clientX - rect.left) / canvas.clientWidth) * 2 - 1;
        this.mouse.y = -((event.clientY - rect.top) / canvas.clientHeight) * 2 + 1;
        // 射線檢測
        this.raycaster.setFromCamera(this.mouse, this.camera);
        const intersects = this.raycaster.intersectObjects(this.scene.children, true);
        if (intersects.length > 0) {
            const hitObject = intersects[0].object;
            const bodyPart = this.bodyModelService.findBodyPartValue(hitObject);
            if (bodyPart) {
                // 設置點選位置
                this.clickPosition = {
                    x: event.clientX - rect.left,
                    y: event.clientY - rect.top
                };
                // 記錄選中的部位
                this.lastSelectedPart = bodyPart;
                // 顯示點選成功提示
                this.showClickSuccess();
                // 執行選擇邏輯
                this.bodyModelService.selectBodyPart(bodyPart, intersects[0].point);
                // 發出事件
                this.bodyPartSelected.emit({
                    bodyPart,
                    clickPosition: {
                        x: intersects[0].point.x,
                        y: intersects[0].point.y,
                        z: intersects[0].point.z
                    },
                    timestamp: new Date()
                });
            }
        }
    }
    onMouseMove(event) {
        if (!this.isModelVisible)
            return;
        const canvas = this.canvasRef.nativeElement;
        const rect = canvas.getBoundingClientRect();
        // 更新滑鼠位置
        this.mousePosition = {
            x: event.clientX - rect.left,
            y: event.clientY - rect.top
        };
        this.mouse.x = ((event.clientX - rect.left) / canvas.clientWidth) * 2 - 1;
        this.mouse.y = -((event.clientY - rect.top) / canvas.clientHeight) * 2 + 1;
        // 滑鼠懸停檢測
        this.raycaster.setFromCamera(this.mouse, this.camera);
        const intersects = this.raycaster.intersectObjects(this.scene.children, true);
        if (intersects.length > 0) {
            const hitObject = intersects[0].object;
            const bodyPart = this.bodyModelService.findBodyPartValue(hitObject);
            this.hoveredPart = bodyPart;
            canvas.style.cursor = bodyPart ? 'pointer' : 'default';
        }
        else {
            this.hoveredPart = null;
            canvas.style.cursor = 'default';
        }
    }
    onMouseLeave() {
        this.hoveredPart = null;
        this.canvasRef.nativeElement.style.cursor = 'default';
    }
    onWindowResize() {
        const canvas = this.canvasRef.nativeElement;
        this.camera.aspect = canvas.clientWidth / canvas.clientHeight;
        this.camera.updateProjectionMatrix();
        this.renderer.setSize(canvas.clientWidth, canvas.clientHeight);
    }
    startRenderLoop() {
        const animate = () => {
            this.animationId = requestAnimationFrame(animate);
            this.controls.update();
            this.renderer.render(this.scene, this.camera);
        };
        animate();
    }
    clearSelections() {
        this.bodyModelService.clearAllSelections();
    }
    removePart(part) {
        this.bodyModelService.selectBodyPart(part, new THREE.Vector3());
    }
    exportSelections() {
        const selections = this.bodyModelService.getSelectedValues();
        const exportData = {
            timestamp: new Date().toISOString(),
            selectedParts: this.selectedParts.map(part => ({
                displayName: part.displayName,
                value: part.value,
                medicalCode: part.medicalCode
            }))
        };
        // 匯出為 JSON 檔案
        const dataStr = JSON.stringify(exportData, null, 2);
        const dataBlob = new Blob([dataStr], { type: 'application/json' });
        const url = URL.createObjectURL(dataBlob);
        const link = document.createElement('a');
        link.href = url;
        link.download = `body-parts-selection-${Date.now()}.json`;
        link.click();
        URL.revokeObjectURL(url);
        console.log('匯出選擇:', exportData);
    }
    trackByUuid(index, part) {
        return part.uuid;
    }
    showClickSuccess() {
        // 清除之前的計時器
        if (this.clickNotificationTimeout) {
            clearTimeout(this.clickNotificationTimeout);
        }
        // 顯示提示
        this.showClickNotification = true;
        // 1.5秒後隱藏
        this.clickNotificationTimeout = setTimeout(() => {
            this.showClickNotification = false;
        }, 1500);
    }
    cleanup() {
        // 清除訂閱
        this.subscriptions.forEach(sub => sub.unsubscribe());
        // 停止動畫循環
        if (this.animationId) {
            cancelAnimationFrame(this.animationId);
        }
        // 清除 Three.js 資源
        if (this.renderer) {
            this.renderer.dispose();
        }
        if (this.controls) {
            this.controls.dispose();
        }
        this.bodyModelService.dispose();
    }
}
